using AppCondominio.Modules.Reservations.Domain;
namespace AppCondominio.Modules.Reservations.Application;
public interface IReservationsRepository{Task AddAsync<T>(T entity,CancellationToken ct) where T:class;Task<ReservableArea?> GetAreaAsync(Guid id,CancellationToken ct);Task<Reservation?> GetReservationAsync(Guid id,CancellationToken ct);Task<bool> AreaCodeExistsAsync(Guid communityId,string code,CancellationToken ct);Task<bool> HasOverlapAsync(Guid areaId,DateTimeOffset startsAt,DateTimeOffset endsAt,CancellationToken ct);Task SaveChangesAsync(CancellationToken ct);}
public sealed class ReservationService(IReservationsRepository repository)
{
 public async Task<Guid> CreateAreaAsync(Guid communityId,string code,string name,int capacity,decimal fee,CancellationToken ct){if(await repository.AreaCodeExistsAsync(communityId,code,ct))throw new InvalidOperationException("Area code already exists.");var x=ReservableArea.Create(communityId,code,name,capacity,fee);await repository.AddAsync(x,ct);await repository.SaveChangesAsync(ct);return x.Id;}
 public async Task<Guid> RequestAsync(Guid areaId,Guid requesterId,DateTimeOffset startsAt,DateTimeOffset endsAt,int guests,CancellationToken ct){var area=await repository.GetAreaAsync(areaId,ct)??throw new KeyNotFoundException("Reservable area not found.");if(!area.IsActive)throw new InvalidOperationException("Reservable area is inactive.");if(guests>area.Capacity)throw new InvalidOperationException("Reservation exceeds area capacity.");if(await repository.HasOverlapAsync(areaId,startsAt,endsAt,ct))throw new InvalidOperationException("Reservation overlaps an existing confirmed or pending booking.");var x=Reservation.Create(area.CommunityId,area.Id,requesterId,startsAt,endsAt,guests,area.Fee);await repository.AddAsync(x,ct);await repository.SaveChangesAsync(ct);return x.Id;}
 public async Task ConfirmAsync(Guid id,string by,CancellationToken ct){var x=await repository.GetReservationAsync(id,ct)??throw new KeyNotFoundException("Reservation not found.");if(await repository.HasOverlapAsync(x.AreaId,x.StartsAt,x.EndsAt,ct)){}x.Confirm(by);await repository.SaveChangesAsync(ct);} public async Task CancelAsync(Guid id,string by,CancellationToken ct){var x=await repository.GetReservationAsync(id,ct)??throw new KeyNotFoundException("Reservation not found.");x.Cancel(by);await repository.SaveChangesAsync(ct);} public async Task CompleteAsync(Guid id,CancellationToken ct){var x=await repository.GetReservationAsync(id,ct)??throw new KeyNotFoundException("Reservation not found.");x.Complete();await repository.SaveChangesAsync(ct);}
}